// Helper to get content for today
function getTodayContent() {
  const now = new Date();
  const start = new Date(now.getFullYear(), 0, 0);
  const dayOfYear = Math.floor((now - start) / 86400000);
  return DAILY_CONTENT[dayOfYear % DAILY_CONTENT.length];
}

